import { z } from 'zod'

// ─── Step schemas ─────────────────────────────────────────────────────────────

export const studioStepSchema = z.object({
  studioName: z.string().min(2, 'Studio name must be at least 2 characters.').max(60, 'Studio name must be 60 characters or fewer.'),
  timezone: z.string().min(1, 'Timezone is required.'),
  fullName: z.string().min(2, 'Your name must be at least 2 characters.').max(80, 'Your name must be 80 characters or fewer.'),
  specialties: z.array(z.string()).optional(),
})

export const locationStepSchema = z.object({
  locationName: z.string().min(2, 'Location name must be at least 2 characters.').max(60, 'Location name must be 60 characters or fewer.').default('Main Studio'),
  city: z.string().min(2, 'City must be at least 2 characters.').max(80, 'City must be 80 characters or fewer.'),
  country: z.string().min(2, 'Country is required.').max(80, 'Country must be 80 characters or fewer.'),
  address: z.string().max(200).optional(),
  state: z.string().max(80).optional(),
  zip: z.string().max(20).optional(),
  phone: z.string().max(30).optional(),
})

export const serviceStepSchema = z.object({
  serviceName: z.string().min(2, 'Service name must be at least 2 characters.').max(80, 'Service name must be 80 characters or fewer.'),
  durationMin: z.number().int('Duration must be a whole number.').min(15, 'Duration must be at least 15 minutes.').max(480, 'Duration must be 480 minutes or fewer.'),
  basePrice: z.number().min(0, 'Price must be 0 or more.'),
  depositPct: z.number().min(0, 'Deposit must be 0% or more.').max(100, 'Deposit must be 100% or less.').optional(),
  description: z.string().max(500, 'Description must be 500 characters or fewer.').optional(),
})

// ─── Inferred input types ─────────────────────────────────────────────────────

export type StudioStepInput = z.infer<typeof studioStepSchema>
export type LocationStepInput = z.infer<typeof locationStepSchema>
export type ServiceStepInput = z.infer<typeof serviceStepSchema>

// ─── Discriminated union result type ─────────────────────────────────────────

export type ActionResult<T> =
  | { ok: true; data: T }
  | { ok: false; error: string }

/**
 * Timezone helpers for the onboarding wizard.
 *
 * All Intl API calls are guarded for environments (older Node, some edge runtimes)
 * that may not support Intl.supportedValuesOf.
 */

// ─── Minimal fallback list (used when Intl.supportedValuesOf is unavailable) ──

const FALLBACK_TIMEZONES: string[] = [
  'Africa/Cairo',
  'Africa/Johannesburg',
  'America/Chicago',
  'America/Denver',
  'America/Los_Angeles',
  'America/New_York',
  'America/Sao_Paulo',
  'America/Toronto',
  'Asia/Dubai',
  'Asia/Kolkata',
  'Asia/Seoul',
  'Asia/Shanghai',
  'Asia/Singapore',
  'Asia/Tokyo',
  'Australia/Melbourne',
  'Australia/Sydney',
  'Europe/Amsterdam',
  'Europe/Berlin',
  'Europe/Istanbul',
  'Europe/London',
  'Europe/Madrid',
  'Europe/Paris',
  'Pacific/Auckland',
  'Pacific/Honolulu',
  'UTC',
]

// ─── detectBrowserTimezone ────────────────────────────────────────────────────

/**
 * Returns the user's IANA timezone string detected via the Intl API.
 * Falls back to 'UTC' if detection fails.
 * Only meaningful in browser context — in Node it returns the system timezone.
 */
export function detectBrowserTimezone(): string {
  try {
    return Intl.DateTimeFormat().resolvedOptions().timeZone || 'UTC'
  } catch {
    return 'UTC'
  }
}

// ─── getAllTimezones ──────────────────────────────────────────────────────────

/**
 * Returns all IANA timezones grouped by continent.
 * Excludes 'Etc/*' entries and bare 'UTC' (noisy machine strings).
 *
 * Falls back to a hardcoded minimal list when Intl.supportedValuesOf is
 * unavailable (some Node versions, older browsers).
 */
export function getAllTimezones(): Record<string, string[]> {
  let allZones: string[]

  try {
    if (typeof Intl.supportedValuesOf === 'function') {
      allZones = Intl.supportedValuesOf('timeZone')
    } else {
      allZones = FALLBACK_TIMEZONES
    }
  } catch {
    allZones = FALLBACK_TIMEZONES
  }

  const groups: Record<string, string[]> = {}

  for (const tz of allZones) {
    // Only include entries containing '/' (excludes bare 'UTC')
    if (!tz.includes('/')) continue
    // Exclude Etc/* — machine-legible noise
    if (tz.startsWith('Etc/')) continue

    const slashIndex = tz.indexOf('/')
    const continent = tz.slice(0, slashIndex)

    if (!groups[continent]) {
      groups[continent] = []
    }
    groups[continent].push(tz)
  }

  return groups
}

// ─── formatTimezoneLabel ──────────────────────────────────────────────────────

/**
 * Formats an IANA timezone string into a human-readable label.
 *
 * 'America/New_York' → 'New York (GMT-5)'
 *
 * Uses the current date to compute the UTC offset (handles DST correctly —
 * the offset reflects the actual current offset, not the standard one).
 */
export function formatTimezoneLabel(tz: string): string {
  try {
    // Extract the location portion (after the last '/')
    const parts = tz.split('/')
    const location = (parts[parts.length - 1] ?? tz).replace(/_/g, ' ')

    // Compute the UTC offset using a known date (today — DST-aware)
    const now = new Date()
    const formatter = new Intl.DateTimeFormat('en-US', {
      timeZone: tz,
      timeZoneName: 'shortOffset',
    })
    const formatted = formatter.format(now)

    // Extract the GMT offset from the formatted string (e.g. 'GMT-5', 'GMT+5:30')
    const offsetMatch = formatted.match(/GMT[+-]\d+(:\d+)?/)
    const offset = offsetMatch ? offsetMatch[0] : 'GMT+0'

    return `${location} (${offset})`
  } catch {
    // If the timezone is invalid or formatting fails, return the raw string
    return tz
  }
}

