'use server'

import { createClient } from '@/lib/supabase/server'
import { logAuditAction } from '@/lib/audit'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { slugify } from '@/lib/utils'
import { BOOKING_DOMAIN } from '@/lib/onboarding/constants'
import {
  studioStepSchema,
  locationStepSchema,
  serviceStepSchema,
  type ActionResult,
} from '@/lib/onboarding/schemas'
import { headers } from 'next/headers'

// ─── Types ────────────────────────────────────────────────────────────────────

export interface OnboardingStateSnapshot {
  studioId: string | null
  studio: {
    id: string
    name: string
    slug: string
    timezone: string
    onboarded_at: string | null
  } | null
  counts: {
    locations: number
    services: number
    artists: number
  }
  resumeAt: 1 | 2 | 3 | 4
  fullName: string | null
}

// ─── Internal helpers ─────────────────────────────────────────────────────────

/**
 * Returns the requesting IP for rate-limit keying.
 * Falls back to 'unknown' when the header is absent (local dev).
 */
async function getClientIp(): Promise<string> {
  const hdrs = await headers()
  return hdrs.get('x-forwarded-for') ?? hdrs.get('x-real-ip') ?? 'unknown'
}

/**
 * Validates the authenticated user owns the given studio.
 * Returns { userId, supabase } on success, or { error } on failure.
 */
async function requireStudioOwnership(studioId: string): Promise<
  | { userId: string; supabase: Awaited<ReturnType<typeof createClient>>; error?: never }
  | { error: ActionResult<never>; userId?: never; supabase?: never }
> {
  const supabase = await createClient()

  const {
    data: { user },
    error: authError,
  } = await supabase.auth.getUser()

  if (authError || !user) {
    return { error: { ok: false, error: 'Not authenticated.' } }
  }

  const { data: member, error: memberError } = await supabase
    .from('studio_members')
    .select('role')
    .eq('studio_id', studioId)
    .eq('user_id', user.id)
    .single()

  if (memberError || !member) {
    return { error: { ok: false, error: 'Studio not found.' } }
  }

  if (member.role !== 'owner') {
    return { error: { ok: false, error: 'Only the studio owner can complete onboarding.' } }
  }

  return { userId: user.id, supabase }
}

/**
 * Returns a unique slug by appending 4 random hex chars if the given slug
 * is already taken by another studio.
 */
async function resolveUniqueStudioSlug(
  supabase: Awaited<ReturnType<typeof createClient>>,
  currentStudioId: string,
  slug: string,
): Promise<string> {
  const { data: conflict } = await supabase
    .from('studios')
    .select('id')
    .eq('slug', slug)
    .neq('id', currentStudioId)
    .maybeSingle()

  if (!conflict) return slug

  // Append 4 random hex chars to make it unique
  const suffix = Math.floor(Math.random() * 0xffff)
    .toString(16)
    .padStart(4, '0')
  return `${slug}-${suffix}`
}

/**
 * Returns a unique slug for a service within a studio.
 */
async function resolveUniqueServiceSlug(
  supabase: Awaited<ReturnType<typeof createClient>>,
  studioId: string,
  slug: string,
): Promise<string> {
  const { data: conflict } = await supabase
    .from('services')
    .select('id')
    .eq('studio_id', studioId)
    .eq('slug', slug)
    .maybeSingle()

  if (!conflict) return slug

  const suffix = Math.floor(Math.random() * 0xffff)
    .toString(16)
    .padStart(4, '0')
  return `${slug}-${suffix}`
}

// ─── saveStudioStep ───────────────────────────────────────────────────────────

export async function saveStudioStep(
  studioId: string,
  input: unknown,
): Promise<ActionResult<{ slug: string }>> {
  const ip = await getClientIp()
  const { success: allowed } = await authedRatelimit.limit(ip)
  if (!allowed) {
    return { ok: false, error: 'Too many requests. Please wait a moment and try again.' }
  }

  const ownership = await requireStudioOwnership(studioId)
  if (ownership.error) return ownership.error

  const { userId, supabase } = ownership

  const parsed = studioStepSchema.safeParse(input)
  if (!parsed.success) {
    return { ok: false, error: parsed.error.errors[0]?.message ?? 'Invalid input.' }
  }
  const data = parsed.data

  // Load current studio to get the existing slug
  const { data: currentStudio, error: studioFetchError } = await supabase
    .from('studios')
    .select('id, slug')
    .eq('id', studioId)
    .single()

  if (studioFetchError || !currentStudio) {
    logger.error({ studioId, err: studioFetchError }, 'saveStudioStep: studio fetch failed')
    return { ok: false, error: "We couldn't save this step. Try again, or refresh the page." }
  }

  // Compute new slug from studio name
  const rawSlug = slugify(data.studioName)
  let finalSlug = currentStudio.slug

  if (rawSlug && rawSlug !== currentStudio.slug) {
    finalSlug = await resolveUniqueStudioSlug(supabase, studioId, rawSlug)
  }

  // Update studios
  const { error: studioUpdateError } = await supabase
    .from('studios')
    .update({ name: data.studioName, timezone: data.timezone, slug: finalSlug })
    .eq('id', studioId)

  if (studioUpdateError) {
    logger.error({ studioId, err: studioUpdateError }, 'saveStudioStep: studio update failed')
    return { ok: false, error: "We couldn't save this step. Try again, or refresh the page." }
  }

  // Update profile full_name
  const { error: profileUpdateError } = await supabase
    .from('profiles')
    .update({ full_name: data.fullName })
    .eq('id', userId)

  if (profileUpdateError) {
    logger.error({ userId, err: profileUpdateError }, 'saveStudioStep: profile update failed')
    // Non-fatal — do not block the onboarding flow
  }

  // Upsert artists row for the owner.
  // artists table has a unique index on (studio_id, slug) — not (studio_id, user_id).
  // profile_id links to profiles.id which equals the auth user.id.
  // We check by (studio_id, profile_id) then insert or update.
  const artistSlug = slugify(data.fullName)
  const resolvedArtistSlug = await resolveUniqueServiceSlug(
    supabase,
    studioId,
    artistSlug,
  ).catch(() => artistSlug) // non-critical; reuse slug if resolution fails

  const { data: existingArtist } = await supabase
    .from('artists')
    .select('id, slug')
    .eq('studio_id', studioId)
    .eq('profile_id', userId)
    .maybeSingle()

  if (existingArtist) {
    const { error: artistUpdateError } = await supabase
      .from('artists')
      .update({
        display_name: data.fullName,
        specialties: data.specialties ?? [],
      })
      .eq('id', existingArtist.id)

    if (artistUpdateError) {
      logger.error({ studioId, userId, err: artistUpdateError }, 'saveStudioStep: artist update failed')
    }
  } else {
    const { error: artistInsertError } = await supabase
      .from('artists')
      .insert({
        studio_id: studioId,
        profile_id: userId,
        display_name: data.fullName,
        specialties: data.specialties ?? [],
        slug: resolvedArtistSlug || null,
      })

    if (artistInsertError) {
      logger.error({ studioId, userId, err: artistInsertError }, 'saveStudioStep: artist insert failed')
    }
  }

  await logAuditAction(userId, 'onboarding.studio_saved', { type: 'studio', id: studioId }, null, studioId)

  return { ok: true, data: { slug: finalSlug } }
}

// ─── saveLocationStep ─────────────────────────────────────────────────────────

export async function saveLocationStep(
  studioId: string,
  input: unknown,
): Promise<ActionResult<{ locationId: string }>> {
  const ip = await getClientIp()
  const { success: allowed } = await authedRatelimit.limit(ip)
  if (!allowed) {
    return { ok: false, error: 'Too many requests. Please wait a moment and try again.' }
  }

  const ownership = await requireStudioOwnership(studioId)
  if (ownership.error) return ownership.error

  const { userId, supabase } = ownership

  const parsed = locationStepSchema.safeParse(input)
  if (!parsed.success) {
    return { ok: false, error: parsed.error.errors[0]?.message ?? 'Invalid input.' }
  }
  const data = parsed.data

  const { data: location, error: insertError } = await supabase
    .from('locations')
    .insert({
      studio_id: studioId,
      name: data.locationName,
      city: data.city,
      country: data.country,
      is_primary: true,
      ...(data.address ? { address: data.address } : {}),
      ...(data.state ? { state: data.state } : {}),
      ...(data.zip ? { zip: data.zip } : {}),
      ...(data.phone ? { phone: data.phone } : {}),
    })
    .select('id')
    .single()

  if (insertError || !location) {
    logger.error({ studioId, err: insertError }, 'saveLocationStep: location insert failed')
    return { ok: false, error: "We couldn't save this step. Try again, or refresh the page." }
  }

  await logAuditAction(userId, 'onboarding.location_saved', { type: 'location', id: location.id }, null, studioId)

  return { ok: true, data: { locationId: location.id } }
}

// ─── saveServiceStep ──────────────────────────────────────────────────────────

export async function saveServiceStep(
  studioId: string,
  input: unknown,
): Promise<ActionResult<{ serviceId: string }>> {
  const ip = await getClientIp()
  const { success: allowed } = await authedRatelimit.limit(ip)
  if (!allowed) {
    return { ok: false, error: 'Too many requests. Please wait a moment and try again.' }
  }

  const ownership = await requireStudioOwnership(studioId)
  if (ownership.error) return ownership.error

  const { userId, supabase } = ownership

  const parsed = serviceStepSchema.safeParse(input)
  if (!parsed.success) {
    return { ok: false, error: parsed.error.errors[0]?.message ?? 'Invalid input.' }
  }
  const data = parsed.data

  const basePriceCents = Math.round(data.basePrice * 100)
  const depositPct = data.depositPct ?? 0
  const depositCents = Math.round((depositPct / 100) * basePriceCents)
  const depositRequired = depositPct > 0

  const rawSlug = slugify(data.serviceName)
  const finalSlug = await resolveUniqueServiceSlug(supabase, studioId, rawSlug)

  const { data: service, error: insertError } = await supabase
    .from('services')
    .insert({
      studio_id: studioId,
      name: data.serviceName,
      slug: finalSlug,
      description: data.description ?? null,
      duration_min: data.durationMin,
      base_price_cents: basePriceCents,
      deposit_cents: depositCents,
      deposit_required: depositRequired,
      is_public: true,
      sort_order: 0,
    })
    .select('id')
    .single()

  if (insertError || !service) {
    logger.error({ studioId, err: insertError }, 'saveServiceStep: service insert failed')
    return { ok: false, error: "We couldn't save this step. Try again, or refresh the page." }
  }

  await logAuditAction(userId, 'onboarding.service_saved', { type: 'service', id: service.id }, null, studioId)

  return { ok: true, data: { serviceId: service.id } }
}

// ─── completeOnboarding ───────────────────────────────────────────────────────

export async function completeOnboarding(
  studioId: string,
): Promise<ActionResult<{ bookingUrl: string }>> {
  const ip = await getClientIp()
  const { success: allowed } = await authedRatelimit.limit(ip)
  if (!allowed) {
    return { ok: false, error: 'Too many requests. Please wait a moment and try again.' }
  }

  const ownership = await requireStudioOwnership(studioId)
  if (ownership.error) return ownership.error

  const { userId, supabase } = ownership

  // Idempotent — only stamp if not already set
  const { error: updateError } = await supabase
    .from('studios')
    .update({ onboarded_at: new Date().toISOString() })
    .eq('id', studioId)
    .is('onboarded_at', null)

  if (updateError) {
    logger.error({ studioId, err: updateError }, 'completeOnboarding: update failed')
    return { ok: false, error: "We couldn't complete onboarding. Try again, or refresh the page." }
  }

  const { data: studio, error: slugFetchError } = await supabase
    .from('studios')
    .select('slug')
    .eq('id', studioId)
    .single()

  if (slugFetchError || !studio) {
    logger.error({ studioId, err: slugFetchError }, 'completeOnboarding: slug fetch failed')
    return { ok: false, error: "We couldn't complete onboarding. Try again, or refresh the page." }
  }

  await logAuditAction(userId, 'onboarding.completed', { type: 'studio', id: studioId }, null, studioId)

  return { ok: true, data: { bookingUrl: `${BOOKING_DOMAIN}/${studio.slug}` } }
}

// ─── getOnboardingState ───────────────────────────────────────────────────────

export async function getOnboardingState(): Promise<OnboardingStateSnapshot> {
  const supabase = await createClient()

  const {
    data: { user },
    error: authError,
  } = await supabase.auth.getUser()

  if (authError || !user) {
    return {
      studioId: null,
      studio: null,
      counts: { locations: 0, services: 0, artists: 0 },
      resumeAt: 1,
      fullName: null,
    }
  }

  // Fetch studio membership with studio details in a single PostgREST call
  const { data: memberRow } = await supabase
    .from('studio_members')
    .select('studio_id, studios(id, name, slug, timezone, onboarded_at)')
    .eq('user_id', user.id)
    .is('deactivated_at', null)
    .order('joined_at', { ascending: true })
    .limit(1)
    .single()

  if (!memberRow) {
    return {
      studioId: null,
      studio: null,
      counts: { locations: 0, services: 0, artists: 0 },
      resumeAt: 1,
      fullName: null,
    }
  }

  const studioData = Array.isArray(memberRow.studios)
    ? memberRow.studios[0]
    : memberRow.studios

  if (!studioData) {
    return {
      studioId: memberRow.studio_id,
      studio: null,
      counts: { locations: 0, services: 0, artists: 0 },
      resumeAt: 1,
      fullName: null,
    }
  }

  const studioId = memberRow.studio_id

  // Fetch counts in parallel
  const [locationsResult, servicesResult, artistsResult, profileResult] = await Promise.all([
    supabase
      .from('locations')
      .select('id', { count: 'exact', head: true })
      .eq('studio_id', studioId),
    supabase
      .from('services')
      .select('id', { count: 'exact', head: true })
      .eq('studio_id', studioId),
    supabase
      .from('artists')
      .select('id', { count: 'exact', head: true })
      .eq('studio_id', studioId)
      .eq('profile_id', user.id),
    supabase
      .from('profiles')
      .select('full_name')
      .eq('id', user.id)
      .single(),
  ])

  const counts = {
    locations: locationsResult.count ?? 0,
    services: servicesResult.count ?? 0,
    artists: artistsResult.count ?? 0,
  }

  const studio = {
    id: studioData.id,
    name: studioData.name,
    slug: studioData.slug,
    timezone: studioData.timezone,
    onboarded_at: studioData.onboarded_at,
  }

  const fullName = profileResult.data?.full_name ?? null

  // Compute resume step
  let resumeAt: 1 | 2 | 3 | 4

  const hasDefaultName = studio.name === 'My Studio' || !studio.name
  const hasNoTimezone = !studio.timezone

  if (hasDefaultName || hasNoTimezone) {
    resumeAt = 1
  } else if (counts.locations === 0) {
    resumeAt = 2
  } else if (counts.services === 0) {
    resumeAt = 3
  } else {
    resumeAt = 4
  }

  return {
    studioId,
    studio,
    counts,
    resumeAt,
    fullName,
  }
}

/**
 * Ambient type declaration for the PostHog browser snippet.
 *
 * PostHog is loaded via script tag (not the npm package) so window.posthog
 * is not typed by default. This declaration silences TypeScript errors and
 * avoids @ts-ignore usage in components.
 *
 * Only `capture` is typed here — add further methods as needed.
 */
interface Window {
  posthog?: {
    capture?: (event: string, properties?: Record<string, unknown>) => void
  }
}

